custom_css:
@import url("https://fontsapi.zeoseven.com/285/main/result.css");
@import url("https://fontsapi.zeoseven.com/292/main/result.css");
@font-face {
    font-family: 'DroidSansChinese';
    src: url("https://files.catbox.moe/lqwl9u.ttf") format('truetype'); /* 修改为新的字体链接 */
    font-weight: normal; /* 设置字体粗细为400 */
    font-style: normal;
}
body, button, input, textarea, code, select {
  font-family:  var(--mainfont), "Microsoft YaHei", sans-serif !important;
}
:root {
    --mainfont: Noto Serif CJK;
    --black30a: var(--SmartThemeBotMesBlurTintColor);
    --golden: var(--SmartThemeQuoteColor);
    --white50a: #62708294;
    --black50a: transparent;
}
/* 自定义元素 */
:root{
/* 顶部图标 */
    --topbar_icon: url(https://i.postimg.cc/4dd4YPCb/1.png);
/* 顶部图标大小 */
    --topbar_icon_size: 15px;
/* 复选框图标 */
    --check_icon: url(https://i.postimg.cc/SKWBvMQW/10.png);
/* 小铅笔图标 */
    --pencil_icon1: url(https://i.postimg.cc/bwqdvFpK/3.png);
/* 小铅笔边上的图标 */
    --pencil_icon2: url(https://i.postimg.cc/hPj5qK7w/4.png);
/* 发送按钮 */
    --send_icon: url(https://i.postimg.cc/BnBFbpJ8/7.png);
/* 不知道叫啥总之输入框是第1个图标 */
    --send_icon1: url(https://i.postimg.cc/gJV5z1sB/5.png);
/* 不知道叫啥总之输入框是第2个图标 */
    --send_icon2: url(https://i.postimg.cc/9Q2DT9fv/6.png);
/* 等待消息猫爪图标 */
    --waiting_icon: url(https://i.postimg.cc/L6QHFZng/8.png);
/* 输入框按钮通用大小 */
    --send_icon_size: 25px;
}





/* 隐藏滑动条 */
*{
  scrollbar-width: none; /* Firefox */
  -ms-overflow-style: none; /* IE/Edge */
}

/* WebKit浏览器 (Chrome/Safari) */
*::-webkit-scrollbar {
  display: none;
  width: 0;
  height: 0;
}
#chat {
    padding: 0px 2px;
    display: flex
;
    align-items: center !important;
    backdrop-filter: none;
}
#chat .mes {
    display: flex
;
    flex-direction: column;
    margin: 50px 0px 20px !important;
    position: relative;
}
#chat .mesAvatarWrapper {
    display: flex
;
    flex-direction: row;
    height: 50px;
    align-items: flex-end;
}
.last_mes .mesAvatarWrapper {
    padding-bottom: 0px;
}
.mes_block .ch_name {
    max-width: 80%;
    min-height: 22px;
    align-items: stretch;
    display: flex
;
    flex-direction: row;
    z-index: 2;
}
.mes .mes_timer, .mes .mesIDDisplay, .mes .tokenCounterDisplay {
    font-weight: normal;
    margin-top: 0px;
    margin-right: 15px;
    border-radius: 5px;
    padding: 0px 8px;
    background: var(--SmartThemeBlurTintColor);
    backdrop-filter: blur(20px) !important
}
.mes_block {
    margin-top: -50px;
    padding: 0px;
}
.mes_text {
    margin: 30px 0px 0px;
    /* 保持你原本的 10px，不增加内部间距 */
    padding: 18px; 

    background: var(--SmartThemeBlurTintColor);
    backdrop-filter: blur(10px) !important;
    text-align: justify;

    /* 新增：20px 圆角，变得和输入框一样圆润 */
    border-radius: 20px;

    /* 新增：确保气泡能撑开到最大宽度 */
    width: auto;
    max-width: 100%;
    box-sizing: border-box;
}

}

}
#chat .avatar img {
    width: var(--avatar-base-width);
    height: var(--avatar-base-height);
    border: 2px solid var(--SmartThemeBotMesBlurTintColor);
    box-shadow: 0 0 15px var(--SmartThemeBotMesBlurTintColor);
}
.mes .avatar {
    position: absolute;
    left: 20px;
}
#chat .mes_block .ch_name{
    margin: 5px 0px 0px 60px;
}
.mes[is_user="true"] .mes_timer{
    margin-right: 0px;
} 
.mesIDDisplay {
    margin-left: 70px;
}
/* 思维链 */
.mes_reasoning_details .mes_reasoning_summary {
    height: 40px;
    margin-top: 5px;
    margin-bottom: -15px;
}
.mes_reasoning_header_block {
    flex-direction: column;
    align-items: center;
    position: relative;
    height: 40px;
}
.mes_reasoning_header {
    background: transparent;
    position: relative;
    color:transparent;
}
.mes_reasoning_header_block::after {
    content: "⚝°.✩┈…୨୧…┈✩.° 𝐓𝐰𝐢𝐧-𝐖𝐢𝐧𝐠 𝐈𝐧𝐬𝐞𝐜𝐭 °.✩┈…୨୧…┈✩.°";
    position: absolute;
    bottom: 0px;
    position-area: center;
    font-size: 0.9em !important;
}
.mes_reasoning {
    margin: 40px 0px 0px 0px;
    text-align: justify;
    background:  var(--SmartThemeBlurTintColor);
    backdrop-filter: blur(10px);
}
#chat .alignItemsBaseline {
    align-items: center !important;
    padding: 1px 10px;
    background: var(--SmartThemeBlurTintColor);
    backdrop-filter: blur(10px);
    border-radius: 10px;
    flex-direction: row;
    margin-left: 10px;
}
.drawer-content .alignItemsBaseline {
    background:  var(--SmartThemeBlurTintColor);
    backdrop-filter: blur(10px);
    padding: 5px 5px 5px 10px;
    border-radius: 20px !important;
}

/* 顶部 */
#top-bar{
   box-shadow: none !important;
}
#top-settings-holder .drawer-toggle{
    padding: 0 !important; /* 移除内边距 */
    width: fit-content !important; /* 自适应图标宽度 */
}
#top-settings-holder .drawer-icon{
    padding: 4px; /* 图标周围保留4px点击区域 */
    font-size: 20px !important; /* 可选：缩小图标尺寸 */
    color:transparent;
}
#sys-settings-button .drawer-toggle, #WI-SP-button .drawer-toggle, #logo_block .drawer-toggle, #table_database_settings_drawer .drawer-toggle, #rightNavHolder .drawer-toggle, #advanced-formatting-button .drawer-toggle, #user-settings-button .drawer-toggle, #ai-config-button .drawer-toggle, #extensions-settings-button .drawer-toggle, #persona-management-button .drawer-toggle {
    background-image: var(--topbar_icon) !important;
    background-repeat: no-repeat;
    background-position: center;
    background-size: contain;
    height: var(--topbar_icon_size);
    display: inline-block;
    color: transparent;
}
#extensionTopBar {
    border-radius: 0px !important;
}
/* 编辑按钮 */
/* 编辑按钮 */
.mes_button, .extraMesButtons>div {
    filter: none;
}
#chat .mes .ch_name .fa-pencil:before, .fa-ellipsis-h:before {
    background-image: var(--pencil_icon1);
    background-repeat: no-repeat;
    color: transparent;
    font-size: 20px;
    background-size: contain;
}
 .fa-ellipsis:before{
    background-image: var(--pencil_icon2);
    background-repeat: no-repeat;
    color: transparent;
    font-size: 20px;
    background-size: contain;
}
#send_form {
    height: auto !important;
    min-height: 55px !important;
    border-radius:20px;
    width: -webkit-fill-available;
    border-color: transparent !important;
    margin: 0px 15px;
    flex-direction: row !important;
    justify-content: center !important;
    align-items: center;
    padding:10px;
}
.fa-bars::before,
.fa-magic-wand-sparkles::before{
    display: none !important; /* 隐藏 Font Awesome 图标 */
}

#send_but::before{
    display: none !important; /* 隐藏 Font Awesome 图标 */
}

#options_button {
    background-image: var( --send_icon1) !important;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    width: var(--send_icon_size) !important;
    height: var(--send_icon_size) !important;
}
#extensionsMenuButton {
    background-image: var(--send_icon2) !important;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    width: var(--send_icon_size)!important;
    height: var(--send_icon_size) !important;
    margin-left: 10px !important;
}
/* 替换 "发送消息" (纸飞机按钮) */
#send_but {
    background-image: var( --send_icon) !important;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    width: var(--send_icon_size) !important;
    height: var(--send_icon_size)  !important;
}
.fa-solid.fa-circle-stop {
    /* 隐藏Font Awesome的字体图标 */
    font-size: 0 !important;
    color: transparent !important;

    /* 用自定义图片替换 */
    display: inline-block;
    width: var(--send_icon_size) !important;
    height: var(--send_icon_size) !important;
    background-image: var(--waiting_icon) ;
    background-repeat: no-repeat;
    background-size: contain;

    /* 新增的呼吸悬浮动画 */
    animation: float-and-breathe 3s ease-in-out infinite;
}

/* 定义呼吸悬浮动画的关键帧 */
@keyframes float-and-breathe {
    0%, 100% {
        transform: translateY(0) scale(1);
    }
    50% {
        transform: translateY(-5px) scale(1.1);
    }
}
/* 底栏QR按键隐藏 */
#send_form:hover #qr--bar {
    height: 35px;
    transition: all 0.5s ease;
}
#qr--bar {
    height: 0.5px;
}

#quick-reply-rocket-button {
    font-size: 0.8em !important;
    margin-right: 5px !important;
}


.reasoning_edit_textarea, .edit_textarea {
    background-color: var(--SmartThemeShadowColor);
    border: 1px dashed var(--SmartThemeQuoteColor);
}
.mes_edit_buttons {
    filter: none;
}
.mes_edit_buttons .menu_button, .mes_reasoning_actions .edit_button {
    background: var(--SmartThemeBotMesBlurTintColor);
    margin-top: 20px;
    margin-bottom: -20px;
}
.reasoning_edit_textarea {
    margin-top: 40px;
}
/* 导入框 */
#extensions_settings .inline-drawer-toggle.inline-drawer-header, #extensions_settings2 .inline-drawer-toggle.inline-drawer-header, #user-settings-block h4, .standoutHeader, .userSettingsInnerExpandable, #tagInput, #completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
    background: var(--SmartThemeUserMesBlurTintColor);
    box-shadow: 0px 2px 2px var(--SmartThemeShadowColor);
    padding: 6px 12px !important;
    border-radius: 10px !important;
}
select {
    background: var(--SmartThemeUserMesBlurTintColor) !important;
    padding: 6px 6px 6px 12px !important;
    border-radius: 15px !important;
}
.fa-chevron-circle-up:before, .fa-circle-chevron-up:before, .fa-chevron-circle-down:before, .fa-circle-chevron-down:before {
    content: "\f1ce";
    font-size: 0.8em;
}
/* 滑块 */
/* 清除所有浏览器默认外框 */
input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;
    margin: 0;
    padding: 0;
    width: 100%;
    height: 2px;
    border-radius: 0px;
    background-size: 70% 100%;
    background-repeat: no-repeat;
    box-shadow: none;
    cursor: ew-resize;
}
input[type="range"] {
    -webkit-appearance: none !important;
    border-radius: 0px !important;
    height: 1.5px !important;
    background: var(--SmartThemeQuoteColor) !important;
    box-shadow: none !important;
}
input[type="number"] {
    background-color: var(--SmartThemeBlurTintColor) ;
    backdrop-filter: blur(10px);
    border-radius: 0px;
    margin-top: 10px;
}

input[disabled], textarea[disabled] {

}
/* 滑块按钮样式 */
input[type="range"]::-webkit-slider-thumb {
  width:10px;
  height: 10px;
  background: var(--SmartThemeQuoteColor) ;
  cursor: pointer;
  border-radius: 50%;
}
.mes.smallSysMes .mesAvatarWrapper {
    display: none !important;
    height: unset !important;
    min-height: unset;
}

/* 复选框 */
input[type="checkbox"] {
    background: var(--SmartThemeBotMesBlurTintColor);
    border: none;
    box-shadow: none;
    border-radius: 50% !important;
}
input[type="checkbox"]:checked {
    background:     var(--check_icon);
    background-size: contain;
    background-repeat: no-repeat;
    box-shadow: none;
    border: none !important;
    width: 1.5em;
    height: 1.5em;
    outline: none;
}
input[type="checkbox"]::before {
    box-shadow: none;
}
/* 文字框 */
textarea {
    background: var(--SmartThemeBotMesBlurTintColor);
}
.text_pole {
    background-color: var(--SmartThemeBotMesBlurTintColor);
    border-radius: 5px;
    padding: 6px;
}
/* 正则 */
.regex-script-container {
    margin-right: 45px;
}

.regex-script-label {
    border-left: 1.5px solid var(--SmartThemeBotMesBlurTintColor) !important;
    background: var(--SmartThemeShadowColor);
    border-radius: 0px !important;
}
#completion_prompt_manager .completion_prompt_manager_header {
    color: var(--SmartThemeBodyColor);
}
#completion_prompt_manager .completion_prompt_manager_header_advanced span {
    filter: none;
}
/* 预设 */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt .prompt_manager_prompt_controls span {
    filter: none;
}
#completion_prompt_manager #completion_prompt_manager_list {
    background: transparent;
    font-family: var(--mainfont);
}
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled {
    background: transparent;
    box-shadow: none;
    border: none;
}
/* 角色选择 */
.character_select.entity_block.flex-container.interactable.is_fav, #user_avatar_block .bogus_folder_select, #user_avatar_block .character_select, #user_avatar_block .avatar-container.selected {
    outline-offset: -5px;
    background: var(--SmartThemeUnderlineColor);
box-shadow: 1px 2px 6px 3px var(--SmartThemeShadowColor);
    margin: 5px 0px;
    padding: 10px;
    position: relative;
    border: none;
}
.hotswap.avatars_inline.scroll-reset-container {
 flex-wrap: nowrap;
 overflow-y: auto;
 overflow-x: hidden;
 -webkit-overflow-scrolling: touch;
 min-height: 50px;

 /* 添加左右外边距 */
 margin-inline-start: 50px; /* 根据需要调整数值 */
 margin-inline-end: 50px;   /* 与左外边距保持一致 */
}

.character_select.is_fav .avatar, .group_select.is_fav .avatar, .group_member.is_fav .avatar, .avatar.is_fav {
    outline: 2px solid transparent;
}
.character_select.is_fav .ch_name, .group_select.is_fav .ch_name, .group_member.is_fav .ch_name {
    color: #000;
}
.fav_on, .world_set, .toggleEnabled {
    color: #c6c6c6 !important;
}
/* 标签 */
.tag {
    filter: none;
    border: none;
    background: var(--SmartThemeEmColor) !important;
}
.tag.actionable {
    background: var(--SmartThemeEmColor) !important;
    border: none !important;
}
/* 双引号引用 */
.mes_text q {
    font-family: "LXGW WenKai";
    font-weight: normal;
}
mes_text i:not([class*="icon"]):not(i[class^="fa-"]), .mes_text em:not([class*="icon"]):not([class^="fa-"]) {
    font-style: normal;
    background: var(--SmartThemeShadowColor);
    padding: 1px 4px;
    border-left: 1.5px solid var(--SmartThemeEmColor);
    margin: 5px 0px;
    display: inline-block;
}
code {
    color: var(--SmartThemeEmColor);
    border-bottom: 1.5px dashed;
    background: transparent;
    border-radius: 0px;
}
.hljs{
     border-bottom: none !important;
}
.world_entry {
    transition: opacity 500ms;
    background: var(--SmartThemeBlurTintColor);
    margin: 15px 10px;
    border-radius: 10px;
    box-shadow: 3px 2px 3px var(--SmartThemeShadowColor);
}
.mes_text blockquote, .mes_reasoning blockquote {
    border-left: 1.5px solid var(--SmartThemeQuoteColor);
    padding-left: 10px;
    background-color: var(--black30a);
    margin: 0;
}
.hotswap.avatars_inline.scroll-reset-container {
    flex-wrap: wrap;
    overflow-y: auto;
    overflow-x: hidden;
    -webkit-overflow-scrolling: touch;
    min-height: 50px;
    margin-inline-start: 10px;
    margin-inline-end: 10px;
}
.mes_reasoning_header_title{
    height: 40px;
    width: 300px;
}
input, select, button {
    font-family: var(--mainFontFamily), sans-serif;
    font-size: var(--mainFontSize);
    color: rgb(255 255 255 / 75%);
    background: var(--SmartThemeBlurTintColor);
}
